from datetime import datetime

def hydrate_time(nanoseconds, tz=None):
    if nanoseconds < 0:
        raise ValueError("Negative nanoseconds are not supported")
    if tz is None:
        tz = datetime.now().tzname
    return datetime.fromtimestamp(nanoseconds / 1e9 - 3600, tz=tz)

