       include only certain values by index or key.

       :param keys: indexes or keys of the items to include; if none
                    are provided, all values will be included
       :return: list of values
       :rtype: list
       """
    filtered_items = {}
    include_index = kwargs.get('include_index', [])
    include_key = kwargs.get('include_key', [])

    for key in self._items:
        if include_index and key.index in include_index:
            filtered_items[key] = self.get(key.index)
        elif include_key and key.key in include_key:
