def round_half_to_even(n):
    """
        Round half to even, meaning that if the fractional part is 0.5, it rounds to the nearest even integer.
        For example: round_half_to_even(1.5) = 2, round_half_to_even(2.5) = 2,
                     round_half_to_even(3.5) = 4, round_half_to_even(4.5) = 4.

        :param n:
        :return:
    """

    if n.is_integer():
        return int(n)

    fractional_part = n - int(n)
    if fractional_part == 0.5:
        if n > 0:
            return int(n) + 1
        else:
            return int(n) - 1
    else:
        return round(n)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass."""

    if isinstance(fields, str):
        fields = [fields]

    fields_dict = {f: 'float' for f in fields if f != 'x' and f != 'y' and f != 'srid'}

    class BasePoint:
        pass

    class MetaPoint(BasePoint):
        def __init__(self, x=None, y=None, srid=None):
            if srid_map and srid in srid_map:
                srid = srid_map[srid]
            super().__init__()
            self.x = x
            self.y = y
            self.srid = srid

        def __str__(self):
            return f"Point(x={self.x}, y={self.y}, srid={self.srid})"

        def __repr__(self):
            return f"Point({self.x}, {self.y}, {self.srid})"

        def as_dict(self):
            return {'x': self.x, 'y': self.y, 'srid': self.srid}

        def __eq__(self, other):
            return isinstance(other, Point) and self.__dict__ == other.__dict__

        def __hash__(self):
            return hash((self.x, self.y, self.srid))

    return BasePoint, MetaPoint

