def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.

    """
    cache = collections.OrderedDict()
    hit_cache = collections.OrderedDict()

    def decorator(func):
        if ttl <= 0:
            # Increasing the TTL to be greater than zero allows any cached result to be use,
            # regardless of its age.
            ttl = 1

        def wrapper(*args, **kwargs):
            key = func.__name__ + str(args) + str(kwargs)
            if key in cache:
                now = timer()
                if now - cache[key][1] <= ttl:
                    return cache[key][0]
                else:
                    del cache[key]
            result = func(*args, **kwargs)
            if len(cache) < maxSize:
                cache[key] = (result, now)
            else:
                # Find an item that's expired and replace it.
                least_recent = None
                for k, (v, t) in cache.items():
                    if least_recent is None or t < cache[least_recent][1]:
                        least_recent = k
                del cache[least_recent]
                cache[key] = (result, now)
            hit_cache[key] = result
            return cache[key]

        return wrapper

    return decorator

