def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    context.error = context.error if context.error is not None else []
    context.error.extend(self.errors)
    for attribute, value in self._properties.items():
        if isinstance(value, dict):
            for key, subvalue in value.items():
                if isinstance(subvalue, dict):
                    if key not in context.value:
                        context.value[key] = contextualize(subvalue)
                    elif not isinstance(context.value[key], dict):
                        context.value[key] = contextualize({key: subvalue})
                    elif key in context.value[key] and not isinstance(
                            context.value[key][key], dict):
                        context.value[key][key] = contextualize(
                            {key: subvalue})
                else:
                    if key not in context.value:
                        context.value[key] = contextualize(subvalue)
                    elif not isinstance(context.value[key], dict):
                        context.value[key] = contextualize({key: subvalue})
        else:
            if attribute not in context.value:
                context.value[attribute] = contextualize(value)
            elif not isinstance(context.value[attribute], dict):
                context.value[attribute] = contextualize({attribute: value})

