from copy import deepcopy

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1 or level == len(d2):
        flat_d1 = deepcopy(d1)
        flat_d2 = deepcopy(d2)
        difference_result = {}
        for key in flat_d1:
            if key in flat_d2:
                if flat_d1[key] != flat_d2[key]:
                    difference_result[key] = flat_d1[key]
            else:
                difference_result[key] = flat_d1[key]
        return difference_result
    else:
        flat_d1 = deepcopy(d1)
        flat_d2 = deepcopy(d2)
        result = {}
        for key in flat_d1:
            if key not in flat_d2:
                result[key] = flat_d1[key]
        subdifference = difference(flat_d1, flat_d2, level - 1)
        for key, value in subdifference.items():
            result[key] = value
        return result

def fill(self, coord, weight=1):
        """
        Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        if not isinstance(coord, (list, tuple)):
            raise TypeError("coord must be a list or tuple")

        if not isinstance(weight, (int, float)):
            raise TypeError("weight must be an integer or float")

        if len(coord) not in [1, 2]:
            raise ValueError("coord must have 1 or 2 elements")

        x = self.ebins[self.ebins.searchsorted(coord, side='right') - 1]
        if len(coord) == 2:
            y = self.dbins[self.dbins.searchsorted(coord, side='right') - 1]
            if x < self.xmin or x > self.xmax or y < self.ymin or y > self.ymax:
                return
            self.dcounter[y][x] += weight
        else:
            if x < self.xmin or x > self.xmax:
                return
            self.ccounter[x] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding Regular Expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            Regular Expressions. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    messages = []
    for key, value in labels.items():
        if key.startswith('$'):
            messages.append({"key": f"'{key}' does not match the regex [^$.]"} if not isinstance(value, str) else {"value": f"'{value}' does not match the regex [^.$.]"})
        elif not isinstance(key, str):
            messages.append({"key": "'{key}' is not a string"} if not isinstance(value, str) else {"value": f"'{value}' is not a string"})
        elif not isinstance(value, str):
            messages.append({"value": f"'{value}' is not a string"} if not isinstance(key, str) else {"key": f"'{key}' is not a string"})
        else:
            if isinstance(value, list):
                for item in value:
                    if not isinstance(item, str):
                        messages.append({"item": f"'{item}' is not a string"} if not isinstance(key, str) else {"key": f"'{key}' is not a string"})
            else:
                if not isinstance(value, str):
                    messages.append({"value": f"'{value}' is not a string"} if not isinstance(key, str) else {"key": f"'{key}' is not a string"})
    if messages:
        raise ValidationError(messages)

