def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}

    if version in inventory:
        version_data = inventory[version]
        for logical_name, content_files in version_data["file_mappings"].items():
            logical_path_map[logical_name] = content_files

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity:
        raise ValueError("Fixity block cannot be empty")

    if not all(isinstance(x, dict) for x in fixity):
        raise ValueError("Fixity data must be a list of dictionaries")

    for entry in fixity:
        if not isinstance(entry, dict) or not all(key in entry for key in ['sha256', 'path']):
            raise ValueError("Fixity entry must be a dictionary with 'sha256' and 'path' keys")

        if entry['path'] not in manifest_files:
            raise ValueError(f"Fixity entry contains path not listed in manifest: {entry['path']}")

from collections import deque
from typing import List, Optional

def absorb(self, args: List[str]) -> List[str]:

    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A

    Negative absorption::

        A & (~A | B) = A & B
    """
    result = deque()  # Using double-ended queue for efficient0 appending.

    for expr in args:
        if expr:
            # Continuing the backward logical ID to find the corresponding expression.
            while result and result[-1][1] & expr:
                result.pop()

            # Employs saturation logic for absorption.
            if (expr not in result):
                result.append((expr, 1))

            # Employs perfect match logic for negative absorption.
            elif expr == result[-1][0]:
                result.pop()
        else:
            result.append(('--', 0))  # Flags for empty expressions.

    # Constructs the final result from the deque. Retains the input order.
    final_result = []
    for char, occ in result:
        if char == '--':
            final_result.append('')  # employs string container for empty strings too.
        else:
            for i in range(occ):
                final_result.append(char)

    return final_result

