def deep_merge_nodes(nodes):
    merged_nodes = defaultdict(dict)

    for node in nodes:
        key, value = node
        if isinstance(value, dict):
            merged_nodes[key].update(deep_merge_nodes([(node[0], deep_merge_nodes([new_val for n, new_val in node[1].items() if new_val != value[n]])) for node in value.items()]))
        elif isinstance(value, Mapping):
            merged_nodes[key].update(deep_merge_nodes([(node[0], deep_merge_nodes([new_val for n, new_val in node[1].items() if n not in value or value[n] != new_val])) for node in value.items()]))
        else:
            merged_nodes[key] = value

    return list(merged_nodes.items())

