import subprocess

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''

    # Initialize an empty list to store ignored files
    ignored_files = []

    # Retrieve files from git
    try:
        output = subprocess.check_output(['git', 'ls-files', '--cached', '--others', '--exclude-standard'], stderr=subprocess.STDOUT)
        lines = output.decode('utf-8').splitlines()

        # Filter files based on the ignored list
        for file in lines:
            if any(pattern in file for pattern in ignored):
                ignored_files.append(file)
    except subprocess.CalledProcessError as e:
        print(f"Error: {e.output.decode('utf-8').strip()}")
        return ""

    # Sort ignored files alphabetically
    ignored_files.sort()

    # Return the list of ignored files as a single string
    return ', '.join(ignored_files)

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency == "always":
        return None
    pattern = r"(\d+) ([a-z]+)"
    match = re.match(pattern, frequency)
    if not match:
        raise ValueError(f"Invalid frequency format: {frequency}")
    number, unit = match.groups()
    number = int(number)
    if unit == "microseconds":
        return datetime.timedelta(microseconds=number)
    elif unit == "milliseconds":
        return datetime.timedelta(milliseconds=number)
    elif unit == "seconds":
        return datetime.timedelta(seconds=number)
    elif unit == "minutes":
        return datetime.timedelta(minutes=number)
    elif unit == "hours":
        return datetime.timedelta(hours=number)
    elif unit == "days":
        return datetime.timedelta(days=number)
    elif unit == "weeks":
        return datetime.timedelta(weeks=number)
    else:
        raise ValueError(f"Unsupported unit: {unit}")

