def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    :param pattern: pattern to convert
    :param strip: whether to strip greedy match flag from the pattern
    :return: regex pattern
    """
    if isinstance(pattern, re.Pattern):
        return pattern
    elif isinstance(pattern, str):
        if strip:
            pattern = pattern.rstrip(r'*?+{')
        return re.compile(pattern)
    else:
        raise ValueError(" invalid input type for pattern")

import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, list):
        raise TypeError("Input 'commands' must be a list")

    # Set up command program
    command_program = " ".join([str(command) for command in commands])

    # Prepare arguments list
    args_program = ["-a", " ".join([str(arg) for arg in args])] if args else "-a"

    # Generate command list with arguments and program
    arg_list = [command_program, args_program]

    # Set up additional arguments
    if cwd is not None:
        arg_list.append(cwd)
    if verbose:
        arg_list.append("-v")
    if hide_stderr:
        arg_list.append("-s")
    if env is not None:
        env_program = " ".join(f"{k}={v}" for k, v in env.items())
        arg_list.append(env_program)

    # Execute command
    try:
        subprocess.run(arg_list, check=True, capture_output=True, text=True)
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command '{command_program} {args_program}' failed with output:\n{e.output}")
        raise

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    results = defaultdict(set)

    for (child, parent) in graph.triples((None, prop, None)):
        results[parent].add(child)

    unique_roots = set()
    for root, children in results.items():
        if not any(child in children for child in root.parent):
            unique_roots.add(root)

    if roots is None:
        return unique_roots
    else:
        return {root for root in roots if root in unique_roots}

