def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, iface.__class__):
        raise TypeError('candidate is not a subclass of iface')
    props = iface.properties.copy()
    required = props.get('required', [])
    for p in required:
        value = getattr(candidate, p)
        if value is None or not hasattr(value, 'isOn'):
            raise ValueError(f'{candidate.__class__.__name__} missing required property: {p}')
        if not getattr(value, 'isOn'):
            raise ValueError(f'{candidate.__class__.__name__}.{p} is not active')
        prop_type = props.get(p, type(None))
        if prop_type is not None and not isinstance(value, prop_type):
            raise TypeError(f'{candidate.__class__.__name__}.{p} is of the wrong type (expected {prop_type.__name__}, got {value.__class__.__name__})')
    if tentative:
        return True
    return False

