def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    metaclass = None

    # Determine metaclass from explicit __metaclass__
    if explicit_mc is not None:
        metaclass = explicit_mc

    # Determine metaclass from multiple bases
    for base in bases:
        if hasattr(base, '__class__'):
            base_class = base.__class__
            if hasattr(base_class, '__metaclass__'):
                metaclass = base_class.__metaclass__
                break

    return metaclass

