def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""

    # Check if the tag is null or empty
    if not tag or not tag.strip():
        return False

    # Define the tag validation function
    def is_valid_tag(tag_item):
        if tag_item and tag_item[0].isalpha():
            return True
        return False

    # Test the tag and check if it is valid
    first_char = tag[0]
    tag_item = tag[1:]
    if is_valid_tag(tag_item):
        return True
    elif first_char != "_" and not is_valid_tag(tag_item):
        return True

    # Invalid tag
    return False

