import yaml
from ir_validator import (
   (IRValidatorException, ValidationError, ValidationMessage),
    ir_validator
)

def validate_from_content(cls, spec_content=None):
    """""validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("Spec content cannot be None")

    try:
        spec = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Failed to parse spec: {e}")

    missing_fields = []
    for field in cls.spec_fields:
        if field.name not in spec:
            missing_fields.append(field.name)

    if missing_fields:
        raise IRValidatorException(f"Missing mandatory fields: {missing_fields}")

    return spec

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    import os
    if yaml_file is None:
        raise ValueError("YAML file must be supplied")

    if not os.path.isfile(yaml_file):
        raise FileNotFoundError("YAML file does not exist")

    try:
        with open(yaml_file, 'r') as file:
            data = yaml.safe_load(file)

        # Add error handling if any mandatory fields are missing
        if 'mandatory_field1' not in data:
            raise ir_validator.IRValidatorException("Missing mandatory_field1")
        if 'mandatory_field2' not in data:
            raise ir_validator.IRValidatorException("Missing mandatory_field2")

        return data

    except yaml.YAMLError as e:
        raise ir_validator.IRValidatorException(f"Error parsing YAML file: {e}")

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}

    # Process arguments from the spec
    for arg in self.spec.args:
        if arg.default is not NoDefault:
            defaults[arg.name] = arg.default

    # Process arguments from other sources
    for arg in self.args:
        if arg.default is not NoDefault and not arg.name in defaults:
            defaults[arg.name] = arg.default

    return defaults

