def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
            condition
    """
    if not options_spec:
        return []

    required_args = set()
    for spec_option in options_spec:
        if spec_option and spec_option.has('required_when'):
            match = True
            match_args = spec_option.required_when.keys() if spec_option.required_when else []
            for arg in args:
                if arg not in match_args:
                    match = False
                    break
            if match:
                required_args.add(spec_option.name)

    return list(required_args)

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for key, value in args.items():
        if not isinstance(value, int):
            raise ValueError(f"Argument '{key}' must be an integer")

        if value < 0:
            raise ValueError(f"Argument '{key}' cannot be less than 0")

        if value > self.max_length:
            raise ValueError(f"Argument '{key}' exceeds maximum length of {self.max_length}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    choices = ['option1', 'option2', 'option3']  # Define your available choices here
    for arg in args:
        if arg not in choices:
            raise ValueError(f"Invalid choice value: {arg}, available choices are {choices}.")

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    min_val = getattr(self.params, 'min_val', None)
    max_val = getattr(self.params, 'max_val', None)

    if not all((min_val is not None, max_val is not None)):
        raise ValueError("Both minimum and maximum values must be provided")

    for arg in args:
        if arg < min_val or arg > max_val:
            raise ValueError("Argument {} is out of the valid range [{} - {}]".format(arg, min_val, max_val))

